package org.aiupcycler.worker.engine

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import java.io.File

/**
 * The committed tiny GGUF fixtures (regenerated byte-identically by
 * `cargo run -p ai-upcycler-model-io --example fixture_dump -- <res dir>`)
 * must parse to the exact shape the Rust reader produces in
 * `model-io/src/gguf.rs`: same required keys, same alignment math, same
 * out-of-bounds and malformed-file refusals.
 */
class GgufReaderTest {

    @get:Rule
    val tmp = TemporaryFolder()

    private fun fixture(name: String): File {
        val url = javaClass.getResource("/engine/fixtures/$name")
            ?: error("missing fixture resource /engine/fixtures/$name")
        return File(url.toURI())
    }

    @Test
    fun untiedF32FixtureParsesToTheEngineShape() {
        fixture("tiny-untied-f32.gguf").let { file ->
            GgufFile.open(file).use { gguf ->
                assertEquals("tiny-untied-f32", gguf.modelName)
                with(gguf.hparams) {
                    assertEquals(4, blockCount)
                    assertEquals(64, contextLength)
                    assertEquals(64, embeddingLength)
                    assertEquals(128, feedForwardLength)
                    assertEquals(4, headCount)
                    assertEquals(2, headCountKv)
                    assertEquals(16, headDim)
                    assertEquals(1e-5f, rmsEps)
                    assertEquals(10000f, ropeTheta)
                }
                // Untied: the head is an own `output.weight`, and all four
                // blocks carry the nine required per-block tensors.
                assertTrue(gguf.tensor("output.weight") != null)
                assertTrue(gguf.tensor("token_embd.weight") != null)
                assertTrue(gguf.tensor("output_norm.weight") != null)
                for (i in 0 until 4) {
                    assertEquals(
                        "blk.$i.attn_q.weight missing",
                        true,
                        gguf.tensor("blk.$i.attn_q.weight") != null,
                    )
                    assertEquals(
                        "blk.$i.ffn_down.weight missing",
                        true,
                        gguf.tensor("blk.$i.ffn_down.weight") != null,
                    )
                }
                assertTrue(gguf.tensor("blk.4.attn_norm.weight") == null)
            }
        }
    }

    @Test
    fun untiedF32ReadRawBoundsAndSizes() {
        fixture("tiny-untied-f32.gguf").let { file ->
            GgufFile.open(file).use { gguf ->
                val emb = gguf.tensor("token_embd.weight")!!
                // GGML dims are innermost-first: ne[0] = hidden (64), ne[1] = vocab (256).
                assertEquals(64L, emb.ne[0])
                assertEquals(256L, emb.ne[1])
                assertEquals(64L * 256L * 4L, emb.nbytes)
                assertEquals((64L * 256L * 4L).toInt(), gguf.readRaw("token_embd.weight").size)
                // The raw read is the exact encoded bytes: an F32 row must
                // start with the IEEE bits the fixture writer produced.
                val row = gguf.readRaw("token_embd.weight")
                val first = java.lang.Float.intBitsToFloat(
                    (row[0].toInt() and 0xFF) or
                        ((row[1].toInt() and 0xFF) shl 8) or
                        ((row[2].toInt() and 0xFF) shl 16) or
                        ((row[3].toInt() and 0xFF) shl 24),
                )
                assertTrue("first embedding value $first is not finite", first.isFinite())
            }
        }
    }

    @Test
    fun missingTensorRefuses() {
        fixture("tiny-untied-f32.gguf").let { file ->
            GgufFile.open(file).use { gguf ->
                try {
                    gguf.readRaw("blk.9.attn_norm.weight")
                    error("readRaw must refuse a missing tensor")
                } catch (e: GgufException) {
                    assertTrue(e.message!!.contains("extends past the end of the file"))
                }
            }
        }
    }

    @Test
    fun tiedQ4FixtureCarriesQuantizedProjectionsAndQkvBiases() {
        fixture("tiny-tied-q4-0.gguf").let { file ->
            GgufFile.open(file).use { gguf ->
                assertEquals("tiny-tied-q4-0", gguf.modelName)
                assertEquals(2, gguf.hparams.blockCount)
                // Tied: no own output.weight; the head reuses token_embd.
                assertTrue(gguf.tensor("output.weight") == null)
                // The projection weights are quantized (Q4_0, ggml id 2).
                assertEquals(2, gguf.tensor("blk.1.attn_q.weight")!!.ggmlType)
                // The Qwen 0.5B-class QKV biases are present as F32 tensors.
                assertTrue(gguf.tensor("blk.0.attn_q.bias") != null)
                assertTrue(gguf.tensor("blk.1.attn_k.bias") != null)
                assertTrue(gguf.tensor("blk.1.attn_v.bias") != null)
            }
        }
    }

    @Test
    fun unsupportedQuantFixtureKeepsTheTypeIdVisible() {
        fixture("tiny-q5-1-refusal.gguf").let { file ->
            GgufFile.open(file).use { gguf ->
                assertEquals("tiny-q5-1-refusal", gguf.modelName)
                // The reader cannot size (and the engine refuses) ggml id 7;
                // the id must stay visible exactly like the Rust reader keeps it.
                val q = gguf.tensor("blk.0.attn_q.weight")
                assertTrue(q != null)
                assertEquals(7, q!!.ggmlType)
            }
        }
    }

    @Test
    fun badMagicRefuses() {
        val file = tmp.newFile("bad.gguf")
        file.writeBytes("GGXU".toByteArray(Charsets.US_ASCII) + ByteArray(64))
        try {
            GgufFile.open(file)
            error("open must refuse a non-GGUF file")
        } catch (e: GgufException) {
            assertEquals("not a GGUF file (bad magic)", e.message)
        }
    }

    @Test
    fun truncatedDataSectionRefusesAtOpen() {
        val original = fixture("tiny-tied-q4-0.gguf")
        val bytes = original.readBytes()
        val file = tmp.newFile("cut.gguf")
        file.writeBytes(bytes.copyOfRange(0, bytes.size - 256))
        try {
            GgufFile.open(file)
            error("open must refuse a truncated file")
        } catch (e: GgufException) {
            assertTrue(e.message!!.contains("extends past the end of the file"))
        }
    }

    /** Wrong GGUF version: nothing else to rely on but a loud refusal. */
    @Test
    fun unsupportedVersionRefuses() {
        val bytes = "GGUF".toByteArray(Charsets.US_ASCII) + 2.toLEBytes() + ByteArray(64)
        val file = tmp.newFile("v2.gguf")
        file.writeBytes(bytes)
        try {
            GgufFile.open(file)
            error("open must refuse version 2")
        } catch (e: GgufException) {
            assertEquals("unsupported GGUF version 2 (only version 3)", e.message)
        }
    }

    private fun Int.toLEBytes(): ByteArray = byteArrayOf(
        (this and 0xFF).toByte(),
        ((this shr 8) and 0xFF).toByte(),
        ((this shr 16) and 0xFF).toByte(),
        ((this shr 24) and 0xFF).toByte(),
    )
}
